        numsLen = len(nums)
        res = [1] * numsLen
        t = 1
        p = 1
        for i in range(numsLen):
            if i < numsLen - 1:
                p *= nums[i]
                res[i+1] *= p
            if i > 0:
                t *= nums[numsLen - i]
