class Solution {
public:
    int getSum(int a, int b) {
        // unsigned arithmetic avoids signed-shift overflow on negative numbers
        unsigned x = a, y = b;
        while (y != 0) {
            unsigned carry = (x & y) << 1;
            x ^= y;
            y = carry;
        }
        return (int)x;
    }
};

