class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        int n = s.size();
        vector<bool> dp(n + 1, false);
        dp[n] = true;
        for (int i = n - 1; i >= 0; i--) {
            for (const string& w : wordDict) {
                if (i + (int)w.size() <= n && s.compare(i, w.size(), w) == 0) {
                    dp[i] = dp[i + w.size()];
                }
                if (dp[i]) break;
            }
        }
        return dp[0];
    }
};

