class Solution:
    def combine(self, nums: list[int], target: int) -> list[list[int]]:
        dp = []
        res = []
        def backtrack(i, total):
            if total == target:
                res.append(dp.copy())
                return
            if i == len(nums):
                return
            if total + nums[i] <= target:
                total += nums[i]
                dp.append(nums[i])
                backtrack(i, total)
                tomin = dp.pop()
                total -= tomin
            backtrack(i+1, total)
        backtrack(0,0)
        return res

code_cpp:
class Solution {
public:
    vector<vector<int>> combine(vector<int>& nums, int target) {
        vector<vector<int>> res;
        vector<int> path;
        function<void(int, int)> backtrack = [&](int i, int total) {
            if (total == target) {
                res.push_back(path);
                return;
            }
            if (i == (int)nums.size() || total > target) return;
            // include nums[i] (it can be reused, so stay on i)
            path.push_back(nums[i]);
            backtrack(i, total + nums[i]);
            path.pop_back();
            // skip nums[i]
            backtrack(i + 1, total);
        };
        backtrack(0, 0);
        return res;
    }
};

