    def uniquePaths(self, m: int, n: int) -> int:
        # row[j] = paths to the current row's column j; the first row/column are all 1
        row = [1] * n
        for _ in range(m - 1):
            for j in range(1, n):
                row[j] += row[j - 1]
        return row[n - 1]

