        vector<vector<int>> res = {intervals[0]};
        for (int i = 1; i < (int)intervals.size(); i++) {
            int start = intervals[i][0], end = intervals[i][1];
            if (start <= res.back()[1]) res.back()[1] = max(res.back()[1], end);
            else res.push_back({start, end});
