# 1->2->3->4->5->NULL ; input -> ouput: 5->4->3->2->1->NULL
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    # T: O(n), M: O(1) : iterative
    def reverseList(self, head: ListNode) -> ListNode:
        prev, curr = None, head
        while curr:
            nxt = curr.next
            curr.next = prev
            prev = curr
            curr = nxt
        return prev

    # T: O(n), M: O(n) : recursive
    def recurse(self, head: ListNode) -> ListNode:
        if not head:
            return None
        newHead = head
        if head.next:
            newHead = self.recurse(head.next)
            head.next.next = head
        head.next = None
        return newHead

