class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        unordered_map<char, int> lastSeen;
        int l = 0, res = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            // if s[r] is already inside the window, move l just past its previous position
            auto it = lastSeen.find(s[r]);
            if (it != lastSeen.end() && it->second >= l) l = it->second + 1;
            lastSeen[s[r]] = r;
            res = max(res, r - l + 1);
        }
        return res;
    }
};

