class Solution {
public:
    int characterReplacement(string s, int k) {
        int count[26] = {0};
        int res = 0, l = 0, maxFreq = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            maxFreq = max(maxFreq, ++count[s[r] - 'A']);
            while ((r - l + 1) - maxFreq > k) {
                count[s[l] - 'A']--;
                l++;
            }
            res = max(res, r - l + 1);
        }
        return res;
    }
};

