class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        map<array<int, 26>, vector<string>> groups;
        for (const string& word : strs) {
            array<int, 26> count = {};
            for (char ch : word) count[ch - 'a']++;
            groups[count].push_back(word);
        }
        vector<vector<string>> res;
        for (auto& g : groups) res.push_back(g.second);
        return res;
    }
};

