class Solution {
public:
    string longestPalindrome(string s) {
        int start = 0, resLen = 0, n = s.size();
        for (int i = 0; i < n; i++) {
            for (int odd = 0; odd < 2; odd++) {
                int l = i, r = i + (odd ? 0 : 1);  // odd length centre, then even length centre
                while (l >= 0 && r < n && s[l] == s[r]) {
                    if (r - l + 1 > resLen) {
                        start = l;
                        resLen = r - l + 1;
                    }
                    l--;
                    r++;
                }
            }
        }
        return s.substr(start, resLen);
    }
};

