class Solution {
public:
    int isPalindromicSubSt(string s) {
        int res = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            res += countPalindrome(s, i, i);      // odd length
            res += countPalindrome(s, i, i + 1);  // even length
        }
        return res;
    }

