class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int ROWS = matrix.size(), COLS = matrix[0].size();
        bool firstRowZero = false;
        // row 0 doubles as the column markers; every other row is zeroed once scanned
        for (int r = 0; r < ROWS; r++) {
            bool rowHasZero = false;
            for (int c = 0; c < COLS; c++) {
                if (matrix[r][c] == 0) {
                    matrix[0][c] = 0;
                    rowHasZero = true;
                }
            }
            if (rowHasZero) {
                if (r == 0) firstRowZero = true;
                else fill(matrix[r].begin(), matrix[r].end(), 0);
            }
        }
        for (int c = 0; c < COLS; c++) {
            if (matrix[0][c] == 0) {
                for (int r = 0; r < ROWS; r++) matrix[r][c] = 0;
            }
        }
        if (firstRowZero) fill(matrix[0].begin(), matrix[0].end(), 0);
    }
};

