class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();
        // transpose
        for (int row = 0; row < n; row++) {
            for (int col = row; col < n; col++) {
                swap(matrix[row][col], matrix[col][row]);
            }
        }
        // reverse each row
        for (int row = 0; row < n; row++) {
            reverse(matrix[row].begin(), matrix[row].end());
        }
    }
