        int longest = 0;
        for (int n : numSet) {
            if (!numSet.count(n - 1)) {  // n starts a sequence
                int length = 1;
                while (numSet.count(n + length)) length++;
                longest = max(longest, length);
            }
        }
        return longest;
    }
