class Solution:
    def alienOrder(self, words: list[str]) -> str:
        adj = {c: set() for w in words for c in w}
        for w1, w2 in zip(words, words[1:]):
            if len(w1) > len(w2) and w1.startswith(w2):
                return ""
            for a, b in zip(w1, w2):
                if a != b:
                    adj[a].add(b)
                    break

        visit = {}  # False = visited, True = on current path
        res = []

        def dfs(c):
            if c in visit:
                return visit[c]
            visit[c] = True
            for nei in adj[c]:
                if dfs(nei):
                    return True
            visit[c] = False
            res.append(c)
            return False

        for c in adj:
            if dfs(c):
                return ""
        res.reverse()
        return "".join(res)

code_cpp:
class Solution {
public:
    string alienOrder(vector<string>& words) {
        unordered_map<char, unordered_set<char>> adj;
        for (const string& w : words) {
            for (char c : w) adj[c];
        }
        for (int i = 0; i + 1 < (int)words.size(); i++) {
            const string &w1 = words[i], &w2 = words[i + 1];
            int minLen = min(w1.size(), w2.size());
            // a longer word before its own prefix is invalid
            if (w1.size() > w2.size() && w1.compare(0, minLen, w2) == 0) return "";
            for (int j = 0; j < minLen; j++) {
                if (w1[j] != w2[j]) {
                    adj[w1[j]].insert(w2[j]);
                    break;
                }
            }
        }

        unordered_map<char, bool> visit;  // false = done, true = on the current path
        string res;
        function<bool(char)> dfs = [&](char c) -> bool {
            if (visit.count(c)) return visit[c];
            visit[c] = true;
            for (char nei : adj[c]) {
                if (dfs(nei)) return true;
            }
            visit[c] = false;
            res.push_back(c);
            return false;
        };

        for (auto& entry : adj) {
            if (dfs(entry.first)) return "";
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

