        priority_queue<int, vector<int>, greater<int>> rooms;  // min-heap of end times
        for (auto& iv : intervals) {
            if (!rooms.empty() && rooms.top() <= iv[0]) rooms.pop();
            rooms.push(iv[1]);
        }
        return rooms.size();
    }
