public:
    // Encodes a tree to a single string (preorder, "N" for null).
    string serialize(TreeNode* root) {
        string res;
        function<void(TreeNode*)> dfs = [&](TreeNode* node) {
            if (!node) {
                res += "N,";
                return;
            }
            res += to_string(node->val) + ",";
            dfs(node->left);
            dfs(node->right);
        };
        dfs(root);
        return res;
    }

    // Decodes your encoded data to tree.
    TreeNode* deserialize(string data) {
        vector<string> vals;
        stringstream ss(data);
        string token;
        while (getline(ss, token, ',')) vals.push_back(token);

        int i = 0;
        function<TreeNode*()> dfs = [&]() -> TreeNode* {
            if (vals[i] == "N") {
                i++;
                return nullptr;
            }
            TreeNode* node = new TreeNode(stoi(vals[i]));
            i++;
            node->left = dfs();
            node->right = dfs();
            return node;
        };
        return dfs();
    }
};

