struct TrieNode {
    TrieNode* children[26] = {};
    bool end = false;
};

class WordDictionary {
public:
    WordDictionary() : root(new TrieNode()) {}

    void addWord(string word) {
        TrieNode* cur = root;
        for (char c : word) {
            if (!cur->children[c - 'a']) cur->children[c - 'a'] = new TrieNode();
            cur = cur->children[c - 'a'];
        }
        cur->end = true;
    }

    bool search(string word) {
        return dfs(word, 0, root);
    }

private:
    TrieNode* root;

    bool dfs(const string& word, int i, TrieNode* node) {
        for (int j = i; j < (int)word.size(); j++) {
            char c = word[j];
            if (c == '.') {
                // try every child for the wildcard
                for (TrieNode* child : node->children) {
                    if (child && dfs(word, j + 1, child)) return true;
                }
                return false;
            }
            node = node->children[c - 'a'];
            if (!node) return false;
        }
        return node->end;
    }
};

