class TrieNode:
    def __init__(self):
        self.children = {}
        self.word = None

class Solution:
    def findWords(self, board: list[list[str]], words: list[str]) -> list[str]:
        root = TrieNode()
        for w in words:
            cur = root
            for c in w:
                cur = cur.children.setdefault(c, TrieNode())
            cur.word = w

        ROWS, COLS = len(board), len(board[0])
        res = []

        def dfs(r, c, parent):
            ch = board[r][c]
            node = parent.children[ch]
            if node.word:
                res.append(node.word)
                node.word = None

            board[r][c] = "#"
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < ROWS and 0 <= nc < COLS and board[nr][nc] in node.children:
                    dfs(nr, nc, node)
            board[r][c] = ch

            if not node.children and not node.word:
                del parent.children[ch]  # prune exhausted branch

        for r in range(ROWS):
            for c in range(COLS):
                if board[r][c] in root.children:
                    dfs(r, c, root)
        return res

