struct TrieNode {
    TrieNode* children[26] = {};
    string word;  // non-empty if a word ends here
};

class Solution {
public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        TrieNode* root = new TrieNode();
        for (const string& w : words) {
            TrieNode* cur = root;
            for (char c : w) {
                if (!cur->children[c - 'a']) cur->children[c - 'a'] = new TrieNode();
                cur = cur->children[c - 'a'];
            }
            cur->word = w;
        }

        ROWS = board.size();
        COLS = board[0].size();
        res.clear();
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (root->children[board[r][c] - 'a']) dfs(board, r, c, root);
            }
        }
        return res;
    }

private:
    int ROWS, COLS;
    vector<string> res;

    void dfs(vector<vector<char>>& board, int r, int c, TrieNode* parent) {
        char ch = board[r][c];
        TrieNode* node = parent->children[ch - 'a'];
        if (!node->word.empty()) {
            res.push_back(node->word);
            node->word.clear();  // don't report the same word twice
        }

        board[r][c] = '#';  // mark as used
        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS &&
                board[nr][nc] != '#' && node->children[board[nr][nc] - 'a']) {
                dfs(board, nr, nc, node);
            }
        }
        board[r][c] = ch;

        // prune exhausted branches so later searches stay fast
        bool leaf = node->word.empty();
        for (TrieNode* child : node->children) {
            if (child) leaf = false;
        }
        if (leaf) {
            delete node;
            parent->children[ch - 'a'] = nullptr;
        }
    }
};

