class MedianFinder {
public:
    MedianFinder() {}

    void addNum(int num) {
        small.push(num);
        large.push(small.top());  // move the largest of the small half up
        small.pop();
        if (large.size() > small.size()) {
            small.push(large.top());
            large.pop();
        }
    }

    double findMedian() {
        if (small.size() > large.size()) return small.top();
        return (small.top() + (long long)large.top()) / 2.0;
    }

private:
    priority_queue<int> small;                                // max-heap, smaller half
    priority_queue<int, vector<int>, greater<int>> large;     // min-heap, larger half
};
